# -*- coding: utf-8 -*-
import re
p='src/lalka-2/work/chapter-01/scaffold.txt'
t={345:'— Я трохи була на неї схожа, — провадила літня пані, зітхаючи й киваючи екс-поміщикові. — Отже, моя донька вродлива й молода, уже має дитину і... може, тужить за іншими. Хоча, пане Вірський, присягаюся, я ніколи не чула від неї про таке...',346:'Вона страждає й мовчить, але я здогадуюся, що страждає. Я теж колись мала тридцять років...',347:'— Хто з нас їх не мав! — тяжко зітхнув управитель.',348:'Двері рипнули, і вбігла маленька дівчинка з в’язальними спицями в руках.',349:'— Бабусю! — вигукнула вона. — Я ніколи не закінчу кофтинки для своєї ляльки...',350:'— Геленко! — суворо озвалася старенька. — Ти ж не привіталася...',351:'Дівчинка зробила два реверанси, на які я відповів незграбно, а пан Вірський — як граф. Вона провадила далі, показуючи бабусі спиці, на яких хитався чорний вовняний квадратик.',352:'— Бабусю, скоро зима, а моя лялька не матиме в чому вийти на вулицю... Бабусю, знову спустилася петля.',353:'(Чарівна дитина... Боже милосердний! Чому Стах не її батько? Може, він не шалів би так...)',354:'Бабуся, перепросивши нас, узяла вовну й спиці, а тієї миті до вітальні увійшла пані Ставська...',355:'Мушу визнати: побачивши її, я поводився гідно; а Вірський зовсім утратив голову. Зірвався зі стільця, мов студент, застебнув сюртук ще на один ґудзик, навіть зашарівся й почав белькотіти:',356:'— Дозвольте представити вам пана Ржецького, повіреного нашого господаря...',357:'— Дуже приємно, — відповіла пані Ставська, вклонившись мені й опустивши очі. Але сильний рум’янець і слід тривоги на її обличчі переконали мене, що я тут небажаний гість.',358:'«Почекай! — подумав я. І уявив, що на моєму місці в цій кімнаті Вокульський. — Почекай, зараз переконаю тебе, що нас не треба боятися».',359:'Тим часом пані Ставська, сівши на стілець, так розгубилася, що почала поправляти сукенку доньки. Її мати теж занепала духом, а управитель зовсім отетерів. «Почекайте!» — подумав я, зробив якнайсуворіший вираз обличчя й озвався:',360:'— Давно пані мешкають у цьому домі?',361:'— П’ять років... — відповіла пані Ставська, ще дужче зашарівшись. Її мати аж здригнулася в кріслі.',362:'— Скільки пані платять?',363:'— Двадцять п’ять рублів на місяць... — прошепотіла молода пані. Вона зблідла, почала теребити сукенку й мимоволі кинула на Вірського такий благальний погляд, що... якби я був Вокульським, то негайно освідчився б їй...',364:'— Ми, — додала вона ще тихіше, — ми заборгували панам за липень...'}
ls=open(p,encoding='utf-8').read().splitlines();i=-1;o=[]
for l in ls:
 if l.startswith('**PL:**'):i+=1
 if l=='**UA:**' and i in t:l='**UA:** '+t[i]
 o.append(l)
